using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ClearDisk {
 internal sealed class DirectoryUsageForm:Form {
  readonly SafetyPolicy policy;readonly TextBox root=new TextBox();readonly Button scan=new Button(),choose=new Button(),up=new Button(),drive=new Button(),cancel=new Button(),open=new Button();readonly Label status=new Label(),direct=new Label();readonly DataGridView grid=new DataGridView();readonly ListBox warnings=new ListBox();readonly System.Windows.Forms.Timer pulse=new System.Windows.Forms.Timer();readonly object gate=new object();
  List<DirectoryUsageItem> items=new List<DirectoryUsageItem>();ScanProgress latest;CancellationTokenSource cancellation;bool busy,closing;
  internal DirectoryUsageForm(SafetyPolicy safety){
   policy=safety;Text="目录大小查看";Font=new Font("Microsoft YaHei UI",9);Size=new Size(1150,780);MinimumSize=new Size(980,630);StartPosition=FormStartPosition.CenterParent;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=6};foreach(int height in new[]{45,45,42})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,height));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,95));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));Controls.Add(layout);
   root.ReadOnly=true;root.Dock=DockStyle.Fill;root.Text=policy.ProfileRoot;layout.Controls.Add(root,0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};scan.Text="开始扫描";choose.Text="选择目录";up.Text="上一级";drive.Text="C盘根目录";cancel.Text="取消";open.Text="打开目录";foreach(var button in new[]{scan,choose,up,drive,cancel,open}){button.Size=new Size(125,32);actions.Controls.Add(button);}cancel.Enabled=false;layout.Controls.Add(actions,0,1);
   direct.Dock=DockStyle.Fill;direct.Text="双击子目录进入；所有操作仅读取元数据，系统文件不会被修改。";direct.TextAlign=ContentAlignment.MiddleLeft;layout.Controls.Add(direct,0,2);
   grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.VirtualMode=true;grid.BackgroundColor=Color.White;
   string[] labels={"子目录","逻辑大小","文件数","计量状态","完整路径"};int[] widths={200,135,110,310,460};for(int i=0;i<labels.Length;i++)grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=labels[i],Width=widths[i]});grid.CellValueNeeded+=delegate(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex<0||e.RowIndex>=items.Count)return;var item=items[e.RowIndex];switch(e.ColumnIndex){case 0:e.Value=item.Name;break;case 1:e.Value=item.Measured?(item.Incomplete?"至少 ":"")+Display.Size(item.LogicalBytes):"未知 / 未计量";break;case 2:e.Value=item.Files.ToString("N0");break;case 3:e.Value=item.Status;break;case 4:e.Value=item.Path;break;}};grid.CellDoubleClick+=async delegate(object sender,DataGridViewCellEventArgs e){if(!busy&&e.RowIndex>=0&&e.RowIndex<items.Count)await Navigate(items[e.RowIndex].Path);};layout.Controls.Add(grid,0,3);warnings.Dock=DockStyle.Fill;warnings.HorizontalScrollbar=true;layout.Controls.Add(warnings,0,4);status.Dock=DockStyle.Fill;status.Text="尚未扫描";status.TextAlign=ContentAlignment.MiddleLeft;layout.Controls.Add(status,0,5);
   scan.Click+=async delegate{await Navigate(root.Text);};up.Click+=async delegate{if(root.Text.Length>3)await Navigate(Path.GetDirectoryName(root.Text.TrimEnd('\\')));};drive.Click+=async delegate{await Navigate(@"C:\");};cancel.Click+=delegate{if(cancellation!=null)cancellation.Cancel();};choose.Click+=delegate{using(var picker=new FolderBrowserDialog{Description="选择C盘目录，只读查看其子目录大小",SelectedPath=root.Text,ShowNewFolderButton=false})if(picker.ShowDialog(this)==DialogResult.OK){if(!picker.SelectedPath.StartsWith(@"C:\",StringComparison.OrdinalIgnoreCase)){MessageBox.Show(this,"此工具仅检查C盘。",Text);return;}SelectRoot(picker.SelectedPath);}};
   open.Click+=delegate{string path=grid.CurrentCell!=null&&grid.CurrentCell.RowIndex<items.Count?items[grid.CurrentCell.RowIndex].Path:root.Text;try{using(var pins=new NativeFiles.ParentLocks(Path.Combine(path,".browse")))Process.Start(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),MediaSimilarityScanner.QuoteArgument(path));}catch(Exception e){MessageBox.Show(this,"无法打开目录："+e.Message,Text);}};
   pulse.Interval=180;pulse.Tick+=delegate{ScanProgress value;lock(gate){value=latest;latest=null;}if(value!=null)status.Text="已检查 "+value.Files.ToString("N0")+" 个文件 · "+Display.Size(value.Bytes)+" · "+value.Message;};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){closing=true;e.Cancel=true;cancellation.Cancel();}};FormClosed+=delegate{pulse.Dispose();};
  }
  internal void SelectRoot(string path){if(busy)return;if(String.IsNullOrWhiteSpace(path)||!path.StartsWith(@"C:\",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("请选择C盘绝对目录。");root.Text=NativeFiles.Normalize(path);items.Clear();grid.RowCount=0;grid.Invalidate();warnings.Items.Clear();direct.Text="新目录尚未扫描，请点击开始扫描。";status.Text="尚未扫描";up.Enabled=root.Text.Length>3;}
  internal void LoadReport(DirectoryUsageReport report){root.Text=report.Root;items=report.Items.OrderByDescending(i=>i.LogicalBytes).ToList();grid.RowCount=items.Count;grid.Invalidate();warnings.Items.Clear();foreach(string warning in report.Warnings)warnings.Items.Add(warning);direct.Text="本目录直属文件 "+report.RootFileCount.ToString("N0")+" 个 · "+Display.Size(report.RootFileBytes)+"；下方仅列本层子目录，可双击继续查看。";status.Text=(report.Cancelled?"已取消":report.Incomplete?"已结束（存在未知 / 未检查项）":"扫描完成")+" · 去重逻辑总量 "+Display.Size(report.UniqueLogicalBytes)+" · "+report.UniqueFiles.ToString("N0")+" 个文件 · 跳过/未知 "+report.Skipped.ToString("N0")+" 项";up.Enabled=!busy&&root.Text.Length>3;}
  internal async Task Navigate(string path){if(busy)return;busy=true;foreach(var button in new[]{scan,choose,up,drive,open})button.Enabled=false;cancel.Enabled=true;cancellation=new CancellationTokenSource();pulse.Start();try{var result=await Task.Run(()=>new DirectoryUsageScanner(policy).Scan(path,cancellation.Token,p=>{lock(gate)latest=p;}));pulse.Stop();lock(gate)latest=null;LoadReport(result);}catch(Exception e){status.Text="目录检查未完成："+e.Message;}finally{pulse.Stop();lock(gate)latest=null;cancellation.Dispose();cancellation=null;busy=false;foreach(var button in new[]{scan,choose,drive,open})button.Enabled=true;up.Enabled=root.Text.Length>3;cancel.Enabled=false;if(closing)Close();}}
 }
}
